<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import axios from 'axios'
import BrandLogo from '../components/BrandLogo.vue'
import ThemeToggle from '../components/ThemeToggle.vue'
const route=useRoute(),data=ref<any>({monitors:[],summary:{}}),error=ref(''),loading=ref(true),busy=ref(false),locked=ref(false),token=ref(typeof route.query.token==='string'?route.query.token:'')
const hasSnapshot=ref(false),autoRefresh=ref(true),keyword=ref(''),statusFilter=ref(''),errorStatus=ref(0)
const labels:Record<string,string>={UP:'运行正常',DOWN:'服务故障',DEGRADED:'性能降级',PAUSED:'已暂停',MAINTENANCE:'维护中',PENDING:'等待探测',UNKNOWN:'状态未知'}
const overallLabels:Record<string,string>={UP:'当前运行中服务正常',DOWN:'部分服务发生故障',DEGRADED:'部分服务性能降级',PAUSED:'存在已暂停的服务',MAINTENANCE:'部分服务维护中',PENDING:'等待服务探测数据',UNKNOWN:'暂无足够数据确认服务状态'}
const formatTime=(value:any)=>{if(!value)return '尚未探测';const time=new Date(value);return Number.isNaN(time.getTime())?'时间不可用':time.toLocaleString('zh-CN',{hour12:false})}
const latency=(value:any)=>value==null||!Number.isFinite(Number(value))?'—':Number(value).toFixed(1)+' ms'
const counts=computed(()=>{const result:Record<string,number>={};for(const monitor of data.value.monitors||[])result[monitor.status]=(result[monitor.status]||0)+1;return result})
const filtered=computed(()=>(data.value.monitors||[]).filter((monitor:any)=>(!statusFilter.value||monitor.status===statusFilter.value)&&(!keyword.value.trim()||[monitor.name,monitor.business,monitor.type].join(' ').toLocaleLowerCase().includes(keyword.value.trim().toLocaleLowerCase()))))
const groups=computed(()=>{const result=new Map<string,any[]>();for(const monitor of filtered.value){const name=monitor.business||'未归属业务';const rows=result.get(name)||[];rows.push(monitor);result.set(name,rows)}return [...result].map(([name,monitors])=>({name,monitors}))})
const errorTitle=computed(()=>locked.value?'需要状态页访问令牌':errorStatus.value===404?'状态页不存在或已停用':'状态暂时不可用')
function resetFilters(){keyword.value='';statusFilter.value=''}
let version=0,timer:ReturnType<typeof setInterval>|undefined
async function load(quiet=false){
 const request=++version;busy.value=true;if(!quiet&&!hasSnapshot.value)loading.value=true;error.value=''
 try{
  const response=await axios.get(`/api/v1/public/status/${encodeURIComponent(String(route.params.slug))}/`,{headers:token.value?{'X-Status-Token':token.value}:{},timeout:20000})
  if(request===version){data.value=response.data;hasSnapshot.value=true;locked.value=false;errorStatus.value=0}
 }catch(e:any){
  if(request===version){errorStatus.value=e.response?.status||0;locked.value=errorStatus.value===403;error.value=e.response?.data?.detail||'无法获取最新状态，请稍后重试';if(!hasSnapshot.value||[401,403,404].includes(errorStatus.value)){data.value={monitors:[],summary:{}};hasSnapshot.value=false}}
 }finally{if(request===version){loading.value=false;busy.value=false}}
}
watch(()=>route.fullPath,()=>{token.value=typeof route.query.token==='string'?route.query.token:'';hasSnapshot.value=false;data.value={monitors:[],summary:{}};resetFilters();load()})
onMounted(()=>{load();timer=setInterval(()=>{if(autoRefresh.value&&!busy.value&&!locked.value)load(true)},30000)})
onBeforeUnmount(()=>{version++;if(timer)clearInterval(timer)})
</script>
<template>
 <main class="status" :style="{'--status-theme':data.theme_color||'#2867dc'}" :aria-busy="busy">
  <header>
   <div class="page-identity"><BrandLogo compact/><div><small class="eyebrow">SERVICE STATUS / 服务状态</small><h1>{{data.name||'业务服务状态'}}</h1><p>{{data.description||'实时服务可用性状态'}}</p></div></div>
   <div class="page-actions"><ThemeToggle/><button class="refresh-button" :disabled="busy" @click="load()"><span aria-hidden="true">↻</span> {{busy?'刷新中…':'刷新状态'}}</button></div>
  </header>
  <el-skeleton v-if="loading" :rows="6" animated/>
  <el-result v-else-if="error&&!hasSnapshot" icon="warning" :title="errorTitle" :sub-title="error"><template #extra><form v-if="locked" class="token-form" @submit.prevent="load()"><el-input v-model="token" type="password" show-password placeholder="请输入状态页访问令牌" aria-label="状态页访问令牌"/><el-button native-type="submit" :loading="busy" type="primary">访问</el-button></form><button v-else :disabled="busy" @click="load()">重新加载</button></template></el-result>
  <template v-else>
   <div v-if="error" class="stale-banner" role="alert"><div><b>最新状态同步失败，以下为上次成功获取的快照</b><span>{{error}} · 快照时间 {{formatTime(data.updated_at)}}</span></div><button :disabled="busy" @click="load()">重试</button></div>
   <section class="overall" :class="[data.overall_status?.toLowerCase(),{stale:!!error}]" aria-label="服务总体状态"><div class="overall-icon" aria-hidden="true">{{error?'!':data.overall_status==='UP'?'✓':data.overall_status==='DOWN'?'!':'·'}}</div><div class="overall-copy"><span class="eyebrow">{{error?'LAST KNOWN STATUS / 上次状态':'CURRENT SERVICE STATUS / 当前服务状态'}}</span><h2>{{overallLabels[data.overall_status]||overallLabels.UNKNOWN}}</h2><p>共 {{data.summary.total||0}} 项服务，受影响 {{data.summary.affected||0}} 项<span v-if="error"> · 当前状态尚未确认</span></p></div><div class="snapshot"><span>{{error?'上次快照':'快照更新于'}}</span><b>{{formatTime(data.updated_at)}}</b><small>{{busy?'正在同步最新状态':error?'等待恢复连接':'按实际探测结果展示'}}</small></div></section>
   <section class="status-metrics" aria-label="当前服务数量"><div><span>全部服务</span><b>{{data.summary.total||0}}</b><small>当前发布范围</small></div><div class="good"><span>运行正常</span><b>{{counts.UP||0}}</b><small>当前正常的服务</small></div><div :class="{affected:Number(data.summary.affected)>0}"><span>受影响服务</span><b>{{data.summary.affected||0}}</b><small>故障或性能降级</small></div><div><span>维护 / 暂停 / 待确认</span><b>{{(counts.MAINTENANCE||0)+(counts.PAUSED||0)+(counts.PENDING||0)+(counts.UNKNOWN||0)}}</b><small>不计为运行正常</small></div></section>
   <section class="services-section" aria-label="服务状态明细"><div class="section-heading"><div><h2>服务运行状态</h2><p>查看各业务的当前探测状态和最近响应</p></div><div class="refresh-control"><span class="connection-dot" :class="{warning:!!error}"></span><span>{{error?'同步异常':autoRefresh?'每 30 秒自动刷新':'已暂停自动刷新'}}</span><button class="auto-toggle" :aria-pressed="!autoRefresh" @click="autoRefresh=!autoRefresh">{{autoRefresh?'暂停':'恢复'}}自动刷新</button></div></div>
    <div v-if="data.monitors.length" class="filters"><label class="search"><span>搜索服务</span><input v-model="keyword" type="search" placeholder="服务名称、业务或探测类型" aria-label="搜索服务"/></label><label><span>服务状态</span><select v-model="statusFilter" aria-label="筛选服务状态"><option value="">全部状态</option><option v-for="(label,value) in labels" :key="value" :value="value">{{label}}（{{counts[value]||0}}）</option></select></label><span class="filter-count">显示 {{filtered.length}} / {{data.monitors.length}} 项</span><button v-if="keyword||statusFilter" class="clear-filters" @click="resetFilters">清除筛选</button></div>
    <el-empty v-if="!data.monitors.length" description="暂无可展示的探测任务"/>
    <div v-else-if="!filtered.length" class="no-results" role="status"><b>没有匹配的服务</b><p>请尝试其他关键字或状态。</p><button @click="resetFilters">显示全部服务</button></div>
    <section v-for="group in groups" :key="group.name" class="service-group"><div class="group-heading"><h3>{{group.name}}</h3><span>{{group.monitors.length}} 项服务</span></div><div class="list"><article v-for="m in group.monitors" :key="m.id" :class="m.status?.toLowerCase()"><div class="service-name"><i aria-hidden="true" :class="m.status?.toLowerCase()"></i><div><b>{{m.name}}</b><span class="probe-type">{{m.type}}</span></div></div><div class="metric"><small>最近响应</small><b>{{latency(m.latency_ms)}}</b></div><div class="checked"><small>最近探测</small><time>{{formatTime(m.last_checked_at)}}</time></div><span class="status-badge" :class="m.status?.toLowerCase()">{{labels[m.status]||labels.UNKNOWN}}</span></article></div></section>
   </section>
   <footer><span>HELI MONITOR · 服务可用性状态</span><span>仅展示当前探测快照，不代表历史 SLA 可用率。</span></footer>
  </template>
 </main>
</template>
<style scoped>
.status{max-width:1120px;margin:0 auto;padding:48px 24px 32px;color:var(--text-primary);min-width:0}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:28px}.page-identity{display:flex;gap:16px;align-items:center;min-width:0}.page-identity>div{min-width:0}.page-identity :deep(.brand-logo){width:48px;flex:none}.page-identity :deep(.brand-mark){width:48px;height:48px}.eyebrow{font-size:10px;letter-spacing:.1em;color:var(--muted);line-height:1.7}h1{font-size:28px;margin:4px 0 0;line-height:1.35;overflow-wrap:anywhere}header p{font-size:13px;color:var(--text-secondary);line-height:1.7;margin:7px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.page-actions{display:flex;align-items:center;gap:10px;flex-shrink:0}button,input,select{font:inherit}button{background:var(--surface);color:var(--text-secondary);border:1px solid var(--border);border-radius:8px;padding:8px 12px;font-size:12px;cursor:pointer;line-height:1.5}button:hover{color:var(--status-theme);border-color:var(--status-theme)}button:disabled{opacity:.6;cursor:wait}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--brand);outline-offset:3px}.refresh-button{color:var(--status-theme)}.refresh-button>span{font-size:16px}.overall{display:flex;align-items:center;gap:20px;padding:26px;border:1px solid var(--border);border-top:3px solid var(--status-theme);border-radius:14px;background:var(--surface);--state:var(--text-secondary);--state-soft:var(--surface-subtle)}.overall.up{--state:var(--success);--state-soft:var(--success-soft)}.overall.down{--state:var(--danger);--state-soft:var(--danger-soft)}.overall.degraded{--state:var(--warning);--state-soft:var(--warning-soft)}.overall.maintenance{--state:var(--brand);--state-soft:var(--brand-soft)}.overall.stale{border-top-color:var(--warning)}.overall-icon{width:58px;height:58px;flex:none;display:grid;place-items:center;border-radius:50%;font-size:29px;font-weight:600;color:var(--state);background:var(--state-soft);border:1px solid var(--border)}.overall-copy{flex:1;min-width:0}.overall-copy h2{font-size:20px;color:var(--state);line-height:1.6;margin:4px 0}.overall-copy p{font-size:12px;line-height:1.8;color:var(--text-secondary);margin:0}.snapshot{display:grid;gap:6px;text-align:right;flex-shrink:0}.snapshot span,.snapshot small{font-size:11px;color:var(--muted)}.snapshot b{font-size:12px;color:var(--text-secondary);font-weight:500;font-variant-numeric:tabular-nums}.status-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:18px 0 30px;gap:12px}.status-metrics>div{padding:18px 20px;background:var(--surface);border:1px solid var(--border);border-radius:10px}.status-metrics span,.status-metrics small{display:block;font-size:11px;color:var(--muted);line-height:1.7}.status-metrics b{display:block;font-size:29px;line-height:1.4;margin:6px 0;color:var(--text-primary);font-variant-numeric:tabular-nums}.status-metrics .good b{color:var(--success)}.status-metrics .affected b{color:var(--danger)}.section-heading{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:16px;margin-bottom:16px}.section-heading h2{font-size:18px;margin:0;line-height:1.5}.section-heading p{font-size:12px;color:var(--muted);margin:6px 0 0;line-height:1.7}.refresh-control{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.connection-dot{width:6px;height:6px;border-radius:50%;background:var(--success)}.connection-dot.warning{background:var(--warning)}.auto-toggle{padding:5px 8px;font-size:11px}.filters{display:flex;align-items:end;flex-wrap:wrap;gap:12px;padding:16px;background:var(--surface);border:1px solid var(--border);border-radius:10px;margin-bottom:18px}.filters label{display:flex;flex-direction:column;gap:7px;font-size:11px;color:var(--text-secondary)}.filters .search{flex:1;min-width:200px}.filters input,.filters select{box-sizing:border-box;min-height:36px;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);background:var(--surface);padding:7px 10px;font-size:12px;width:100%}.filters select{min-width:155px}.filter-count{font-size:11px;color:var(--muted);line-height:36px}.clear-filters{font-size:11px;padding:7px 10px}.group-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:20px 2px 10px}.group-heading h3{font-size:14px;margin:0;overflow-wrap:anywhere}.group-heading>span{font-size:11px;color:var(--muted);flex-shrink:0}.list{border:1px solid var(--border);border-radius:10px;background:var(--surface)}.list article{display:grid;grid-template-columns:minmax(0,1fr) 100px 170px 104px;align-items:center;gap:20px;padding:20px;border-bottom:1px solid var(--divider)}.list article:last-child{border-bottom:0}.service-name{display:flex;align-items:center;gap:12px;min-width:0}.service-name i{width:8px;height:8px;flex:none;border-radius:50%;background:var(--muted)}.service-name i.up{background:var(--success)}.service-name i.down{background:var(--danger)}.service-name i.degraded{background:var(--warning)}.service-name i.maintenance{background:var(--brand)}.service-name b{font-size:14px;line-height:1.6;display:block;overflow-wrap:anywhere}.probe-type{display:inline-block;font-size:10px;line-height:1.5;padding:2px 6px;color:var(--muted);background:var(--surface-subtle);border:1px solid var(--divider);border-radius:4px;margin-top:7px}.metric,.checked{display:grid;gap:7px;text-align:right;font-variant-numeric:tabular-nums}.metric small,.checked small{font-size:10px;color:var(--muted)}.metric b{font-size:13px;font-weight:550}.checked time{font-size:11px;color:var(--text-secondary);overflow-wrap:anywhere}.status-badge{text-align:center;font-size:11px;font-weight:550;line-height:1.7;padding:5px 8px;border-radius:6px;color:var(--text-secondary);background:var(--surface-subtle);border:1px solid var(--divider)}.status-badge.up{color:var(--success);background:var(--success-soft)}.status-badge.down{color:var(--danger);background:var(-