@media(max-width:800px){.overall{flex-wrap:wrap;gap:16px}.snapshot{flex:1 1 100%;text-align:left;padding-top:14px;border-top:1px solid var(--divider)}.list article{grid-template-columns:minmax(0,1fr) 100px;gap:14px}.service-name{grid-column:1}.status-badge{grid-row:1;grid-column:2}.metric,.checked{text-align:left}.checked{grid-column:2;grid-row:2}.metric{grid-column:1;grid-row:2}.status-metrics{gap:10px}.status-metrics>div{padding:14px}.status-metrics span{font-size:10px}}
@media(max-width:520px){.status{padding:24px 14px}header{align-items:flex-start;flex-wrap:wrap;gap:18px;margin-bottom:20px}.page-identity{gap:12px}.page-identity :deep(.brand-logo),.page-identity :deep(.brand-mark){width:40px;height:40px}h1{font-size:23px}.eyebrow{font-size:8px}header p{font-size:12px}.page-actions{width:100%;justify-content:flex-end}.overall{padding:18px;gap:13px}.overall-icon{width:44px;height:44px;font-size:24px}.overall-copy h2{font-size:16px}.overall-copy p{font-size:11px}.status-metrics{grid-template-columns:repeat(2,minmax(0,1fr));margin-bottom:24px}.status-metrics b{font-size:26px}.filters{padding:12px;gap:10px}.filters .search{flex-basis:100%;min-width:0}.filters label:not(.search){flex:1;min-width:0}.filters select{min-width:0}.filter-count{line-height:32px}.list article{padding:16px 12px;column-gap:12px;grid-template-columns:minmax(0,1fr) 96px}.service-name{gap:9px}.service-name b{font-size:12px}.status-badge{font-size:10px}.checked time{font-size:10px}.stale-banner{align-items:flex-start;flex-direction:column}.token-form{flex-direction:column}.refresh-control{font-size:10px}footer{display:grid;font-size:10px}.section-heading{gap:12px}}
</style>
